// DONT_TARGET_EXACT_BACKEND: NATIVE
// DUMP_IR
// WITH_STDLIB

// Module `stale` declares classes with the same ClassIds as classes generated by the plugin in module `a`,
// e.g. outputs of a previous build left on the classpath (`target/classes` in Maven builds without `clean`).
// The plugin-generated classes must still get their own members and nested classes in metadata.
// Not on Native: there `b` gets all transitive klibs in a random order and may see `Plain` from `stale` instead of `a`'s.

// MODULE: stale
// FILE: stale.kt
class Plain

class WithNestedFamily

// MODULE: a(stale)
// FILE: src.kt
import org.jetbrains.kotlin.plugin.sandbox.GenerateClassFamily

open class SourceBase

@GenerateClassFamily
class Marker

// MODULE: b(a)
// FILE: main.kt
fun box(): String {
    val plain = Plain()
    if (plain.x != 42) return "FAIL plain.x: ${plain.x}"
    if (plain.foo() != "ok") return "FAIL plain.foo: ${plain.foo()}"

    val inner = WithNestedFamily.Inner()
    if (inner.x != 42) return "FAIL inner.x: ${inner.x}"
    if (WithNestedFamily.fromCompanion() != "from-companion") return "FAIL companion fn"

    return "OK"
}
